256	
257	static int
258	_validate_pin(struct sc_pkcs15_card *p15card, struct sc_pkcs15_auth_info *auth_info, size_t pinlen)
259	{
260		size_t max_length;
261		if (p15card == NULL) {
262			return SC_ERROR_INVALID_ARGUMENTS;
263		}
264	
265		/* Ignore validation of the non-PIN authentication objects */
266		if (auth_info->auth_type != SC_PKCS15_PIN_AUTH_TYPE_PIN)
267			return SC_SUCCESS;
268	
269		/* prevent buffer overflow from hostile card */
270		if (auth_info->attrs.pin.stored_length > SC_MAX_PIN_SIZE)
271			return SC_ERROR_BUFFER_TOO_SMALL;
272	
273		/* if we use pinpad, no more checks are needed */
274		if ((p15card->card->reader->capabilities & SC_READER_CAP_PIN_PAD
275					|| p15card->card->caps & SC_CARD_CAP_PROTECTED_AUTHENTICATION_PATH)
276			   	&& !pinlen)
277			return SC_SUCCESS;
278	
279		/* If pin is given, make sure it is within limits */
280		max_length = auth_info->attrs.pin.max_length != 0 ? auth_info->attrs.pin.max_length : SC_MAX_PIN_SIZE;
281		if (pinlen > max_length || pinlen < auth_info->attrs.pin.min_length)
282			return SC_ERROR_INVALID_PIN_LENGTH;
283	
284		return SC_SUCCESS;
285	}
286	
287	/*
288	 * Verify a PIN.
289	 *
290	 * If the code given to us has zero length, this means we
291	 * should ask the card reader to obtain the PIN from the
292	 * reader's PIN pad
293	 */
294	int
295	sc_pkcs15_verify_pin(struct sc_pkcs15_card *p15card, struct sc_pkcs15_object *pin_obj,
296			const unsigned char *pincode, size_t pinlen)
297	{
298		struct sc_context *ctx = p15card->card->ctx;
299		struct sc_pkcs15_auth_info *auth_info = (struct sc_pkcs15_auth_info *)pin_obj->data;
300		int r;
301	
302		LOG_FUNC_CALLED(ctx);
303	
304		/*
305		 * if pin cache is disabled, we can get here with no PIN data.
306		 * in this case, to avoid error or unnecessary pin prompting on pinpad,
307		 * check if the PIN has been already verified and the access condition
308		 * is still open on card.
309		 */
310		if (pinlen == 0) {
311		    r = sc_pkcs15_get_pin_info(p15card, pin_obj);
312	
313		    if (r == SC_SUCCESS && auth_info->logged_in == SC_PIN_STATE_LOGGED_IN)
314			LOG_FUNC_RETURN(ctx, r);
315		}
316	
317		r = _validate_pin(p15card, auth_info, pinlen);
318	
319		if (r)
320			LOG_FUNC_RETURN(ctx, r);
321	
322		r = _sc_pkcs15_verify_pin(p15card, pin_obj, pincode, pinlen);
323	
324		if (r == SC_SUCCESS)
325			sc_pkcs15_pincache_add(p15card, pin_obj, pincode, pinlen);
326	
327		LOG_FUNC_RETURN(ctx, r);
328	}
329	
330	
331	int
332	_sc_pkcs15_verify_pin(struct sc_pkcs15_card *p15card, struct sc_pkcs15_object *pin_obj,
333			const unsigned char *pincode, size_t pinlen)
334	{
335		return sc_pkcs15_verify_pin_with_session_pin(p15card, pin_obj, pincode,
336				pinlen, NULL, NULL);
337	}
338	
339	/*
340	 * Verify a PIN and generate a session PIN
341	 *
342	 * If the code given to us has zero length, this means we
343	 * should ask the card reader to obtain the PIN from the
344	 * reader's PIN pad
345	 */
346	int sc_pkcs15_verify_pin_with_session_pin(struct sc_pkcs15_card *p15card,
347				 struct sc_pkcs15_object *pin_obj,
348				 const unsigned char *pincode, size_t pinlen,
349				 const unsigned char *sessionpin, size_t *sessionpinlen)
350	{
351		struct sc_context *ctx = p15card->card->ctx;
352		struct sc_pkcs15_auth_info *auth_info = (struct sc_pkcs15_auth_info *)pin_obj->data;
353		int r;
354		sc_card_t *card;
355		struct sc_pin_cmd_data data;
356	
357		LOG_FUNC_CALLED(ctx);
358		sc_log(ctx,
359		       "PIN(type:%X; method:%X; value(%p:%"SC_FORMAT_LEN_SIZE_T"u)",
360		       auth_info->auth_type, auth_info->auth_method,
361		       pincode, pinlen);
362		card = p15card->card;
363	
364		if (pinlen > SC_MAX_PIN_SIZE) {
365			sc_notify_id(card->ctx, &card->reader->atr, p15card,
366					NOTIFY_PIN_BAD);
367			LOG_TEST_RET(ctx, SC_ERROR_INVALID_PIN_LENGTH, "Invalid PIN size");
368		}
369	
370		/* Initialize arguments */
371		memset(&data, 0, sizeof(data));
372		data.pin_type = auth_info->auth_method;
373	
374		if (auth_info->auth_type == SC_PKCS15_PIN_AUTH_TYPE_PIN)   {
375			data.pin_reference = auth_info->attrs.pin.reference;
376			data.pin1.min_length = auth_info->attrs.pin.min_length;
377			data.pin1.max_length = auth_info->attrs.pin.max_length;
378			data.pin1.pad_length = auth_info->attrs.pin.stored_length;
379			data.pin1.pad_char = auth_info->attrs.pin.pad_char;
380			data.pin1.data = pincode;
381			data.pin1.len = pinlen;
382	
383			if (auth_info->attrs.pin.flags & SC_PKCS15_PIN_FLAG_NEEDS_PADDING)
384				data.flags |= SC_PIN_CMD_NEED_PADDING;
385	
386			switch (auth_info->attrs.pin.type) {
387			case SC_PKCS15_PIN_TYPE_BCD:
388				data.pin1.encoding = SC_PIN_ENCODING_BCD;
389				break;
390			case SC_PKCS15_PIN_TYPE_ASCII_NUMERIC:
391				data.pin1.encoding = SC_PIN_ENCODING_ASCII;
392				break;
393			default:
394				/* assume/hope the card driver knows how to encode the pin */
395				data.pin1.encoding = 0;
396			}
397		}
398		else if (auth_info->auth_type == SC_PKCS15_PIN_AUTH_TYPE_AUTH_KEY)   {
399			struct sc_pkcs15_object *skey_obj = NULL;
400			struct sc_pkcs15_id *skey_id =  &auth_info->attrs.authkey.skey_id;
401			struct sc_pkcs15_skey_info *skey_info = NULL;
402	
403			r = sc_pkcs15_find_skey_by_id(p15card, skey_id, &skey_obj);
404			if (r)   {
405				sc_log(ctx, "cannot find secret key with id:%s", sc_pkcs15_print_id(skey_id));
406				LOG_FUNC_RETURN(ctx, r);
407			}
408			skey_info = (struct sc_pkcs15_skey_info *)skey_obj->data;
409	
410			sc_log(ctx, "found secret key '%s'", skey_obj->label);
411			data.pin_reference = skey_info->key_reference;
412		}
413	
414		if ((p15card->card->reader->capabilities & SC_READER_CAP_PIN_PAD
415					|| p15card->card->caps & SC_CARD_CAP_PROTECTED_AUTHENTICATION_PATH)) {
416			if (!pincode && !pinlen)
417				data.flags |= SC_PIN_CMD_USE_PINPAD;
418	
419			if (auth_info->attrs.pin.flags & SC_PKCS15_PIN_FLAG_SO_PIN)
420				data.pin1.prompt = "Please enter SO PIN";
421			else
422				data.pin1.prompt = "Please enter PIN";
423		}
424	
425		if (card->caps & SC_CARD_CAP_SESSION_PIN && sessionpin && sessionpinlen) {
426			/* session pin is requested and supported with standard verification*/
427			data.cmd = SC_PIN_CMD_GET_SESSION_PIN;
428			memcpy(&data.pin2, &data.pin1, sizeof (data.pin1));
429			data.pin2.data = sessionpin;
430			data.pin2.len = *sessionpinlen;
431		} else {
432			/* perform a standard verify */
433			data.cmd = SC_PIN_CMD_VERIFY;
434			if (sessionpinlen)
435				*sessionpinlen = 0;
436		}
437	
438		r = sc_lock(card);
439		LOG_TEST_RET(ctx, r, "sc_lock() failed");
440	
441		/* the path in the pin object is optional */
442		if ((auth_info->path.len > 0) || ((auth_info->path.aid.len > 0))) {
443			r = sc_select_file(card, &auth_info->path, NULL);
444			if (r)
445				goto out;
446		}
447	
448		r = sc_pin_cmd(card, &data, &auth_info->tries_left);
449		sc_log(ctx, "PIN cmd result %i", r);
450		if (r == SC_SUCCESS) {
451			sc_pkcs15_pincache_add(p15card, pin_obj, pincode, pinlen);
452			if (data.cmd == SC_PIN_CMD_GET_SESSION_PIN && sessionpinlen) {
453				*sessionpinlen = data.pin2.len;
454			}
455		} else {
456			sc_notify_id(card->ctx, &card->reader->atr, p15card,
457					NOTIFY_PIN_BAD);
458			if (data.cmd == SC_PIN_CMD_GET_SESSION_PIN && sessionpinlen) {
459				*sessionpinlen = 0;
460			}
461		}
462	
463		if (auth_info->auth_type == SC_PKCS15_PIN_AUTH_TYPE_PIN
464				&& auth_info->auth_method != SC_AC_SESSION) {
465			sc_notify_id(card->ctx, &card->reader->atr, p15card,
466					r == SC_SUCCESS ? NOTIFY_PIN_GOOD : NOTIFY_PIN_BAD);
467		}
468	
469	out:
470		sc_unlock(card);
471		LOG_FUNC_RETURN(ctx, r);
472	}
473	
474	
475	
476	/*
477	 * Change a PIN.
478	 */
479	int sc_pkcs15_change_pin(struct sc_pkcs15_card *p15card,
480				 struct sc_pkcs15_object *pin_obj,
481				 const u8 *oldpin, size_t oldpinlen,
482				 const u8 *newpin, size_t newpinlen)
483	{
484		struct sc_context *ctx = p15card->card->ctx;
485		struct sc_pin_cmd_data data;
486		struct sc_pkcs15_auth_info *auth_info = (struct sc_pkcs15_auth_info *)pin_obj->data;
487		struct sc_card *card;
488		int r;
489	
490		LOG_FUNC_CALLED(ctx);
491		if (auth_info->auth_type != SC_PKCS15_PIN_AUTH_TYPE_PIN)
492			LOG_FUNC_RETURN(ctx, SC_ERROR_NOT_SUPPORTED);
493	
494		/* make sure the pins are in valid range */
495		r = _validate_pin(p15card, auth_info, oldpinlen);
496		LOG_TEST_RET(ctx, r, "Old PIN value do not conform PIN policy");
497	
498		r = _validate_pin(p15card, auth_info, newpinlen);
499		LOG_TEST_RET(ctx, r, "New PIN value do not conform PIN policy");
500	
501		card = p15card->card;
502		r = sc_lock(card);
503		LOG_TEST_RET(ctx, r, "sc_lock() failed");
504		/* the path in the pin object is optional */
505		if ((auth_info->path.len > 0) || ((auth_info->path.aid.len > 0))) {
506			r = sc_select_file(card, &auth_info->path, NULL);
507			if (r)
508				goto out;
509		}
510	
511		/* set pin_cmd data */
512		memset(&data, 0, sizeof(data));
513		data.cmd             = SC_PIN_CMD_CHANGE;
514		data.pin_type        = SC_AC_CHV;
515		data.pin_reference   = auth_info->attrs.pin.reference;
516		data.pin1.data       = oldpin;
517		data.pin1.len        = oldpinlen;
518		data.pin1.pad_char   = auth_info->attrs.pin.pad_char;
519		data.pin1.min_length = auth_info->attrs.pin.min_length;
520		data.pin1.max_length = auth_info->attrs.pin.max_length;
521		data.pin1.pad_length = auth_info->attrs.pin.stored_length;
522		data.pin2.data       = newpin;
523		data.pin2.len        = newpinlen;
524		data.pin2.pad_char   = auth_info->attrs.pin.pad_char;
525		data.pin2.min_length = auth_info->attrs.pin.min_length;
526		data.pin2.max_length = auth_info->attrs.pin.max_length;
527		data.pin2.pad_length = auth_info->attrs.pin.stored_length;
528	
529		if (auth_info->attrs.pin.flags & SC_PKCS15_PIN_FLAG_NEEDS_PADDING)
530			data.flags |= SC_PIN_CMD_NEED_PADDING;
531	
532		switch (auth_info->attrs.pin.type) {
533		case SC_PKCS15_PIN_TYPE_BCD:
534			data.pin1.encoding = SC_PIN_ENCODING_BCD;
535			data.pin2.encoding = SC_PIN_ENCODING_BCD;
536			break;
537		case SC_PKCS15_PIN_TYPE_ASCII_NUMERIC:
538			data.pin1.encoding = SC_PIN_ENCODING_ASCII;
539			data.pin2.encoding = SC_PIN_ENCODING_ASCII;
540			break;
541		}
542	
543		if((!oldpin || !newpin)
544				&& (p15card->card->reader->capabilities & SC_READER_CAP_PIN_PAD
545					|| p15card->card->caps & SC_CARD_CAP_PROTECTED_AUTHENTICATION_PATH)) {
546			data.flags |= SC_PIN_CMD_USE_PINPAD;
547			if (auth_info->attrs.pin.flags & SC_PKCS15_PIN_FLAG_SO_PIN) {
548				data.pin1.prompt = "Please enter SO PIN";
549				data.pin2.prompt = "Please enter new SO PIN";
550			}
551			else {
552				data.pin1.prompt = "Please enter PIN";
553				data.pin2.prompt = "Please enter new PIN";
554			}
555		}
556	
557		r = sc_pin_cmd(card, &data, &auth_info->tries_left);
558		if (r == SC_SUCCESS)
559			sc_pkcs15_pincache_add(p15card, pin_obj, newpin, newpinlen);
560	
561	out:
562		sc_unlock(card);
563		return r;
564	}
565	
566	/*
567	 * Unblock a PIN.
568	 */
569	int sc_pkcs15_unblock_pin(struct sc_pkcs15_card *p15card,
570				 struct sc_pkcs15_object *pin_obj,
571				 const u8 *puk, size_t puklen,
572				 const u8 *newpin, size_t newpinlen)
573	{
574		struct sc_context *ctx = p15card->card->ctx;
575		struct sc_pin_cmd_data data;
576		struct sc_pkcs15_object *puk_obj;
577		struct sc_pkcs15_auth_info *puk_info = NULL;
578		struct sc_pkcs15_auth_info *auth_info = (struct sc_pkcs15_auth_info *)pin_obj->data;
579		struct sc_card *card = p15card->card;
580		int r;
581	
582		LOG_FUNC_CALLED(ctx);
583		if (auth_info->auth_type != SC_PKCS15_PIN_AUTH_TYPE_PIN)
584			LOG_FUNC_RETURN(ctx, SC_ERROR_NOT_SUPPORTED);
585	
586		/* make sure the pins are in valid range */
587		r = _validate_pin(p15card, auth_info, newpinlen);
588		LOG_TEST_RET(ctx, r, "New PIN value do not conform PIN policy");
589	
590		/* get pin_info object of the puk (this is a little bit complicated
591		 * as we don't have the id of the puk (at least now))
592		 * note: for compatibility reasons we give no error if no puk object
593		 * is found */
594		/* first step: try to get the pkcs15 object of the puk */
595		r = sc_pkcs15_find_pin_by_auth_id(p15card, &pin_obj->auth_id, &puk_obj);
596		if (r >= 0 && puk_obj) {
597			/* second step:  get the pkcs15 info object of the puk */
598			puk_info = (struct sc_pkcs15_auth_info *)puk_obj->data;
599		}
600	
601		if (!puk_info) {
602			sc_log(ctx, "Unable to get puk object, using pin object instead!");
603			puk_info = auth_info;
604		}
605		/* make sure the puk is in valid range */
606		r = _validate_pin(p15card, puk_info, puklen);
607		LOG_TEST_RET(ctx, r, "PIN do not conforms PIN policy");
608	
609		r = sc_lock(card);
610		LOG_TEST_RET(ctx, r, "sc_lock() failed");
611	
612		/* the path in the pin object is optional */
613		if ((auth_info->path.len > 0) || ((auth_info->path.aid.len > 0))) {
614			r = sc_select_file(card, &auth_info->path, NULL);
615			if (r)
616				goto out;
617		}
618	
619		/* set pin_cmd data */
620		memset(&data, 0, sizeof(data));
621		data.cmd             = SC_PIN_CMD_UNBLOCK;
622		data.pin_type        = SC_AC_CHV;
623		data.pin_reference   = auth_info->attrs.pin.reference;
624		data.pin1.data       = puk;
625		data.pin1.len        = puklen;
626		data.pin1.pad_char   = auth_info->attrs.pin.pad_char;
627		data.pin1.min_length = auth_info->attrs.pin.min_length;
628		data.pin1.max_length = auth_info->attrs.pin.max_length;
629		data.pin1.pad_length = auth_info->attrs.pin.stored_length;
630		data.pin2.data       = newpin;
631		data.pin2.len        = newpinlen;
632		data.pin2.pad_char   = puk_info->attrs.pin.pad_char;
633		data.pin2.min_length = puk_info->attrs.pin.min_length;
634		data.pin2.max_length = puk_info->attrs.pin.max_length;
635		data.pin2.pad_length = puk_info->attrs.pin.stored_length;
636	
637		if (auth_info->attrs.pin.flags & SC_PKCS15_PIN_FLAG_NEEDS_PADDING)
638			data.flags |= SC_PIN_CMD_NEED_PADDING;
639	
640		switch (auth_info->attrs.pin.type) {
641		case SC_PKCS15_PIN_TYPE_BCD:
642			data.pin1.encoding = SC_PIN_ENCODING_BCD;
643			break;
644		case SC_PKCS15_PIN_TYPE_ASCII_NUMERIC:
645			data.pin1.encoding = SC_PIN_ENCODING_ASCII;
646			break;
647		}
648	
649		switch (puk_info->attrs.pin.type) {
650		case SC_PKCS15_PIN_TYPE_BCD:
651			data.pin2.encoding = SC_PIN_ENCODING_BCD;
652			break;
653		case SC_PKCS15_PIN_TYPE_ASCII_NUMERIC:
654			data.pin2.encoding = SC_PIN_ENCODING_ASCII;
655			break;
656		}
657	
658		if((p15card->card->reader->capabilities & SC_READER_CAP_PIN_PAD
659					|| p15card->card->caps & SC_CARD_CAP_PROTECTED_AUTHENTICATION_PATH)) {
660			data.flags |= SC_PIN_CMD_USE_PINPAD;
661			if (auth_info->attrs.pin.flags & SC_PKCS15_PIN_FLAG_SO_PIN) {
662				data.pin1.prompt = "Please enter PUK";
663				data.pin2.prompt = "Please enter new SO PIN";
664			}
665			else {
666				data.pin1.prompt = "Please enter PUK";
667				data.pin2.prompt = "Please enter new PIN";
668			}
669		}
670	
671		r = sc_pin_cmd(card, &data, &auth_info->tries_left);
672		if (r == SC_SUCCESS)
673			sc_pkcs15_pincache_add(p15card, pin_obj, newpin, newpinlen);
674	
675	out:
676		sc_unlock(card);
677		LOG_FUNC_RETURN(ctx, r);
678	}
679	
680	int sc_pkcs15_get_pin_info(struct sc_pkcs15_card *p15card,
681				 struct sc_pkcs15_object *pin_obj)
682	{
683		int r;
684		struct sc_pin_cmd_data data;
685		struct sc_card *card = p15card->card;
686		struct sc_context *ctx = card->ctx;
687		struct sc_pkcs15_auth_info *pin_info = (struct sc_pkcs15_auth_info *) pin_obj->data;
688	
689		LOG_FUNC_CALLED(ctx);
690	
691		r = sc_lock(card);
692		if (r != SC_SUCCESS)
693			return r;
694	
695		if (pin_info->auth_type != SC_PKCS15_PIN_AUTH_TYPE_PIN)   {
696			r = SC_ERROR_INVALID_DATA;
697			goto out;
698		}
699	
700		/* Try to update PIN info from card */
701		memset(&data, 0, sizeof(data));
702		data.cmd = SC_PIN_CMD_GET_INFO;
703		data.pin_type = pin_info->auth_method;
704		data.pin_reference = pin_info->attrs.pin.reference;
705	
706		r = sc_pin_cmd(card, &data, NULL);
707		if (r == SC_SUCCESS) {
708			if (data.pin1.max_tries > 0)
709				pin_info->max_tries = data.pin1.max_tries;
710			/* tries_left must be supported or sc_pin_cmd should not return SC_SUCCESS */
711			pin_info->tries_left = data.pin1.tries_left;
712			pin_info->logged_in = data.pin1.logged_in;
713		}
714	
715	out:
716		sc_unlock(card);
717		LOG_FUNC_RETURN(ctx, r);
718	}
