726	
727	/* Add a PIN to the PIN cache related to the card. Some operations can trigger re-authentication later. */
728	void sc_pkcs15_pincache_add(struct sc_pkcs15_card *p15card, struct sc_pkcs15_object *pin_obj,
729		const u8 *pin, size_t pinlen)
730	{
731		struct sc_context *ctx = p15card->card->ctx;
732		struct sc_pkcs15_auth_info *auth_info = (struct sc_pkcs15_auth_info *)pin_obj->data;
733		struct sc_pkcs15_object *obj = NULL;
734		int r;
735	
736		LOG_FUNC_CALLED(ctx);
737	
738		if (!pin || !pinlen)   {
739			sc_log(ctx, "No cache for zero length PIN");
740			return;
741		}
742		else if (!p15card->opts.use_pin_cache)   {
743			sc_log(ctx, "PIN caching not enabled");
744			return;
745		}
746		else if (auth_info->auth_type != SC_PKCS15_PIN_AUTH_TYPE_PIN)   {
747			sc_log(ctx, "only 'PIN' auth. object can be cached");
748			return;
749		}
750	
751		/* If the PIN protects an object with user consent, don't cache it */
752	
753		obj = p15card->obj_list;
754		while (obj != NULL) {
755			/* Compare 'sc_pkcs15_object.auth_id' with 'sc_pkcs15_pin_info.auth_id'.
756			 * In accordance with PKCS#15 "6.1.8 CommonObjectAttributes" and
757			 * "6.1.16 CommonAuthenticationObjectAttributes" with the exception that
758			 * "CommonObjectAttributes.accessControlRules" are not taken into account. */
759	
760			if (sc_pkcs15_compare_id(&obj->auth_id, &auth_info->auth_id)) {
761				/* Caching is refused, if the protected object requires user consent */
762			    if (!p15card->opts.pin_cache_ignore_user_consent) {
763				if (obj->user_consent > 0) {
764					sc_log(ctx, "caching refused (user consent)");
765					return;
766				}
767			    }
768			}
769	
770			obj = obj->next;
771		}
772	
773		r = sc_pkcs15_allocate_object_content(ctx, pin_obj, pin, pinlen);
774		if (r != SC_SUCCESS)   {
775			sc_log(ctx, "Failed to allocate object content");
776			return;
777		}
778	
779		pin_obj->usage_counter = 0;
780		sc_log(ctx, "PIN(%s) cached", pin_obj->label);
781	}
782	
783	/* Validate the PIN code associated with an object */
784	int
785	sc_pkcs15_pincache_revalidate(struct sc_pkcs15_card *p15card, const sc_pkcs15_object_t *obj)
786	{
787		struct sc_context *ctx = p15card->card->ctx;
788		sc_pkcs15_object_t *pin_obj;
789		int r;
790	
791		LOG_FUNC_CALLED(ctx);
792		if (!p15card->opts.use_pin_cache)
793			return SC_ERROR_SECURITY_STATUS_NOT_SATISFIED;
794	
795		/*  Apps that do not support CK_ALWAYS_AUTHENTICATE
796		 *  may need pin_cache_ignore_user_consent = 1 */
797		if (!p15card->opts.pin_cache_ignore_user_consent) {
798		    if (obj->user_consent)
799			return SC_ERROR_SECURITY_STATUS_NOT_SATISFIED;
800		}
801	
802		if ((p15card->card->reader->capabilities & SC_READER_CAP_PIN_PAD
803					|| p15card->card->caps & SC_CARD_CAP_PROTECTED_AUTHENTICATION_PATH))
804			return SC_ERROR_SECURITY_STATUS_NOT_SATISFIED;
805	
806		r = sc_pkcs15_find_pin_by_auth_id(p15card, &obj->auth_id, &pin_obj);
807		if (r != SC_SUCCESS) {
808			sc_log(ctx, "Could not find pin object for auth_id %s", sc_pkcs15_print_id(&obj->auth_id));
809			return SC_ERROR_SECURITY_STATUS_NOT_SATISFIED;
810		}
811	
812		if (pin_obj->usage_counter >= p15card->opts.pin_cache_counter) {
813			sc_pkcs15_free_object_content(pin_obj);
814			return SC_ERROR_SECURITY_STATUS_NOT_SATISFIED;
815		}
816	
817		if (!pin_obj->content.value || !pin_obj->content.len)
818			return SC_ERROR_SECURITY_STATUS_NOT_SATISFIED;
819	
820		pin_obj->usage_counter++;
821		r = _sc_pkcs15_verify_pin(p15card, pin_obj, pin_obj->content.value, pin_obj->content.len);
822		if (r != SC_SUCCESS) {
823			/* Ensure that wrong PIN isn't used again */
824			sc_pkcs15_free_object_content(pin_obj);
825	
826			sc_log(ctx, "Verify PIN error %i", r);
827			return SC_ERROR_SECURITY_STATUS_NOT_SATISFIED;
828		}
829	
830		LOG_FUNC_RETURN(ctx, SC_SUCCESS);
831	}
832	
833	void sc_pkcs15_pincache_clear(struct sc_pkcs15_card *p15card)
834	{
835		struct sc_pkcs15_object *objs[32];
836		int i, r;
837	
838		LOG_FUNC_CALLED(p15card->card->ctx);
839		r = sc_pkcs15_get_objects(p15card, SC_PKCS15_TYPE_AUTH_PIN, objs, 32);
840		for (i = 0; i < r; i++)
841			sc_pkcs15_free_object_content(objs[i]);
842	}
