88	static int fuzz_reader_connect(sc_reader_t *reader)
89	{
90	    uint16_t chunk_size;
91	    const uint8_t *chunk;
92	
93	    fuzz_get_chunk(reader, &chunk, &chunk_size);
94	
95	    if (chunk_size > reader->atr.len)
96	        chunk_size = reader->atr.len;
97	    else
98	        reader->atr.len = chunk_size;
99	
100	    if (chunk_size > 0)
101	        memcpy(reader->atr.value, chunk, chunk_size);
102	
103	    return SC_SUCCESS;
104	}
