#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
uint8_t *read_hex(const char *fn, size_t *outlen) {
    FILE *f=fopen(fn,"r"); if(!f) return NULL;
    char *line=NULL; size_t cap=0; ssize_t n;
    uint8_t *buf=malloc(1<<20); size_t len=0;
    while((n=getline(&line,&cap,f))>0){
        for(ssize_t i=0;i<n;i++){
            char c=line[i];
            int hi,lo;
            if(c==' '||c=='\n'||c=='\r'||c=='\t') continue;
            int v=c>='0'&&c<='9'?c-'0':(c>='a'&&c<='f'?c-'a'+10:(c>='A'&&c<='F'?c-'A'+10:-1));
            if(v<0) continue;
            /* need pairs */
            // accumulate: read two hex chars
            static int pend=-1;
            if(pend<0){pend=v;} else {buf[len++]=(uint8_t)((pend<<4)|v); pend=-1;}
        }
    }
    free(line); fclose(f); *outlen=len; return buf;
}
int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size);
int main(int argc,char**argv){
    if(argc<2){fprintf(stderr,"usage: %s hexfile\n",argv[0]);return 1;}
    size_t len=0; uint8_t*buf=read_hex(argv[1],&len);
    if(!buf){fprintf(stderr,"read fail\n");return 1;}
    fprintf(stderr,"[main] input %zu bytes\n",len);
    int r=LLVMFuzzerTestOneInput(buf,len);
    fprintf(stderr,"[main] result=%d\n",r);
    return r;
}
EOF
